// Skip Slack post entirely on days with nothing to celebrate — keeps
// the #general channel quiet on ordinary days. Also formats the
// human-readable Slack message from the API payload.
const body = $input.first().json;
const birthdays = body.birthdays ?? [];
const anniversaries = body.anniversaries ?? [];
if (birthdays.length === 0 && anniversaries.length === 0) {
  return [];
}
const lines = [];
if (birthdays.length > 0) {
  lines.push('*🎂 Birthdays today*');
  for (const b of birthdays) {
    const role = b.designation ? ` — ${b.designation}` : '';
    lines.push(`• *${b.name}*${role}. Wishing you a wonderful day! 🎉`);
  }
}
if (anniversaries.length > 0) {
  if (lines.length > 0) lines.push('');
  lines.push('*🎯 Work anniversaries today*');
  for (const a of anniversaries) {
    const yrs = a.years === 1 ? '1 year' : `${a.years} years`;
    const role = a.designation ? ` — ${a.designation}` : '';
    lines.push(`• *${a.name}*${role} completes *${yrs}* at Digital Leap. Cheers to the journey 🥂`);
  }
}
return [{ json: { text: lines.join('\n'), count: birthdays.length + anniversaries.length } }];
